  sd t0, 0(t1)
  li s9, 0
  li t0, 0x0
  csrw satp, t0
  li t0, 0x8000000000080204
  csrw vsatp, t0
  li t0, 0x8000000000080210
  csrw hgatp, t0
  sfence.vma
  hfence.vvma
  hfence.gvma
  li t0, 0xa0a0a0
  csrw medeleg, t0
  li t0, 0xbad0bad1
  csrw mtinst, t0
  csrw htinst, t0
  la t1, recptr
  ld t0, 0(t1)
  la t1, recstart
  sd t0, 0(t1)
  li t0, (3 << 11) | (1 << 39) | (1 << 17)
  csrc mstatus, t0
  li t0, 0x8000000800
  csrs mstatus, t0
  la t0, 2f
  csrw mepc, t0
  la t0, 3f
  la t1, m_cont
  sd t0, 0(t1)
  li a1, 0x140000028
  mret
2:
  la s11, 1f
  ld a2, 24(a1)
1:
  li s9, RETMAGIC
  ecall
3:
  li s9, 0
  jal ra, post_case
  la t0, recstart
  ld s1, 0(t0)
  la s2, name_21
  ld s3, 40(s1)
  ld t0, 8(s1)
  li t1, 'H'
  bne t0, t1, 8f
  ld t0, 16(s1)
  li t1, 21
  bne t0, t1, 8f
  li t1, 0x3000
  beq s3, t1, 7f
  ld t0, 48(s1)
  bnez t0, 8f
  beqz s3, 7f
8:
  li s4, 1
  j 9f
7:
  li s4, 0
9:
  jal ra, report

finish:
  li t0, (1 << 17)
  csrc mstatus, t0
  csrw satp, zero
  bnez s8, 1f
  RVMODEL_HALT_PASS
1:
  RVMODEL_HALT_FAIL

.data
